def main():
    before = (RES / "mipmap-xxxhdpi/ic_launcher.png").stat().st_size if (RES / "mipmap-xxxhdpi/ic_launcher.png").exists() else 0
    print("  before : mipmap-xxxhdpi/ic_launcher.png = %d bytes" % before)

    # back up anything being replaced
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as z:
        names = z.namelist()
        for name in names:
            dest = RES / name
            if dest.exists():
                bak = dest.with_suffix(dest.suffix + ".before-icons")
                if not bak.exists():
                    shutil.copy2(dest, bak)
        z.extractall(RES)
        print("  wrote  : %d files into %s" % (len(names), RES))

    after = (RES / "mipmap-xxxhdpi/ic_launcher.png").stat().st_size
    print("  after  : mipmap-xxxhdpi/ic_launcher.png = %d bytes" % after)

    if after < 20000:
        sys.exit("\nFAILED - the icon still looks like the stock template.\n"
                 "Send me this output and I will adjust the patch.")

    print("")
    print("launcher icon : green book + speech bubble, all densities")
    print("adaptive icon : foreground and background layers written")
    print("splash        : drawable, drawable-port-mdpi, drawable-land-mdpi")
    print("")
    print("OK - all checks passed.")

if __name__ == "__main__":
    main()
